/**
 * 把 zod 定义导出为 JSON Schema，供非 TypeScript 实现方（例如 Runtime 换成 Python）使用。
 * 运行：npm run schema
 */
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { z } from 'zod';

import {
  Envelope,
  PROTOCOL_VERSION,
  APP_SERVER_ALLOWED_METHODS,
  APP_SERVER_NOTIFICATIONS,
  APP_SERVER_SERVER_REQUESTS,
  ApprovalResponse,
  PermissionsApprovalResponse,
  UserInputResponse,
  ElicitationResponse,
  DynamicToolCallParams,
  DynamicToolCallResponse,
  UserInteractionArgs,
  UserInteractionResponse,
  USER_INTERACTION_REQUEST_METHOD,
  runtimeMethods,
  runtimeNotifications,
  STUDIO_DYNAMIC_TOOLS,
  SKILL_CREATION_DYNAMIC_TOOLS,
  RUNTIME_ERROR_CODES,
} from '../src/index';

const outDir = join(dirname(fileURLToPath(import.meta.url)), '..', 'schema');
mkdirSync(outDir, { recursive: true });

function write(name: string, value: unknown) {
  writeFileSync(join(outDir, name), `${JSON.stringify(value, null, 2)}\n`);
  console.log(`wrote schema/${name}`);
}

write('envelope.schema.json', z.toJSONSchema(Envelope));

write('runtime-methods.schema.json', {
  protocolVersion: PROTOCOL_VERSION,
  methods: Object.fromEntries(
    Object.entries(runtimeMethods).map(([name, def]) => [
      name,
      {
        params: z.toJSONSchema(def.params),
        result: z.toJSONSchema(def.result),
      },
    ]),
  ),
  notifications: Object.fromEntries(
    Object.entries(runtimeNotifications).map(([name, schema]) => [name, z.toJSONSchema(schema)]),
  ),
  errorCodes: RUNTIME_ERROR_CODES,
});

write('app-server.schema.json', {
  allowedMethods: APP_SERVER_ALLOWED_METHODS,
  notifications: [...APP_SERVER_NOTIFICATIONS, 'item/reasoning/*'],
  serverRequests: APP_SERVER_SERVER_REQUESTS,
  hostInteractions: { method: USER_INTERACTION_REQUEST_METHOD, params: z.toJSONSchema(UserInteractionArgs), response: z.toJSONSchema(UserInteractionResponse) },
  responses: {
    approval: z.toJSONSchema(ApprovalResponse),
    permissionsApproval: z.toJSONSchema(PermissionsApprovalResponse),
    userInput: z.toJSONSchema(UserInputResponse),
    elicitation: z.toJSONSchema(ElicitationResponse),
    dynamicToolCall: {
      params: z.toJSONSchema(DynamicToolCallParams),
      response: z.toJSONSchema(DynamicToolCallResponse),
    },
  },
});

write('dynamic-tools.json', STUDIO_DYNAMIC_TOOLS);
write('skill-creation-tools.json', SKILL_CREATION_DYNAMIC_TOOLS);
